 ('팀에서 자연스럽게 맡게 되는 자리는?', [('시작하기 쉽게 계획을 정리하는 사람',[8,6,3],['machine','city']),('분위기를 읽고 의견을 이어주는 사람',[7,9,5],['inn','forest']),('필요한 것을 직접 만들어 가져오는 사람',[2,10,0],['neon','castle']),('힘들어 보이는 사람을 챙기는 사람',[4,0,11],['library','sea'])]),
 ('한 가지 도구만 챙길 수 있다. 무엇을 고를까?', [('기록과 생각을 담을 작은 수첩',[6,3,8],['library','city']),('낯선 길을 찾는 나침반',[1,11,0],['sea','space']),('망가진 것도 살리는 수리 도구',[2,10,5],['machine','ruins']),('누군가에게 건넬 약과 따뜻한 음식',[4,5,7],['inn','forest'])]),
 ('일을 마친 뒤 가장 받고 싶은 보상은?', [('다음에도 함께하고 싶다는 신뢰',[7,0,5],['castle','city']),('새로운 곳으로 갈 기회',[1,11,9],['space','sea']),('내 방식으로 몰입할 시간',[3,2,6],['library','neon']),('다 같이 편히 쉬는 한 저녁',[4,10,8],['forest','inn'])]),
 ('좋아하는 일을 위해 감수할 수 있는 어려움은?', [('몸은 힘들어도 눈앞의 문제를 해결하는 것',[0,10,2],['ruins','desert']),('답이 없어도 오래 들여다보는 것',[3,6,11],['library','space']),('사람마다 다른 입장을 조율하는 것',[7,8,5],['city','castle']),('실패해도 새 방식을 다시 시도하는 것',[9,1,2],['neon','machine'])]),
